import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { documentApi } from '../../api/services';
import { Button, Table, Badge, Modal, Pagination } from '../../components/ui';
import { Plus, Trash2, Download } from 'lucide-react';
import toast from 'react-hot-toast';
import { format } from 'date-fns';

const typeColor = { PASSPORT: 'blue', VISA: 'indigo', CONTRACT: 'green', CERTIFICATE: 'yellow', OTHER: 'gray' };

export default function DocumentsPage() {
  const qc = useQueryClient();
  const [page, setPage] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState({ documentType: 'OTHER', expiryDate: '', employeeId: '' });
  const [file, setFile] = useState(null);

  const { data, isLoading } = useQuery({
    queryKey: ['documents', page],
    queryFn: () => documentApi.getAll({ page, size: 20 }),
  });

  const docs = data?.data?.data?.content || data?.data?.data || [];
  const totalPages = data?.data?.data?.totalPages || 0;

  const uploadMutation = useMutation({
    mutationFn: (fd) => documentApi.upload(fd),
    onSuccess: () => { qc.invalidateQueries(['documents']); toast.success('Document uploaded'); setModalOpen(false); },
    onError: (e) => toast.error(e.response?.data?.message || 'Upload failed'),
  });

  const deleteMutation = useMutation({
    mutationFn: documentApi.delete,
    onSuccess: () => { qc.invalidateQueries(['documents']); toast.success('Document deleted'); },
    onError: (e) => toast.error(e.response?.data?.message || 'Failed'),
  });

  const handleUpload = () => {
    if (!file) return toast.error('Please select a file');
    const fd = new FormData();
    fd.append('file', file);
    Object.entries(form).forEach(([k, v]) => v && fd.append(k, v));
    uploadMutation.mutate(fd);
  };

  const columns = [
    { key: 'documentType', label: 'Type', render: (r) => <Badge label={r.documentType} color={typeColor[r.documentType] || 'gray'} /> },
    { key: 'fileName', label: 'File Name' },
    { key: 'expiryDate', label: 'Expiry', render: (r) => r.expiryDate ? format(new Date(r.expiryDate), 'dd MMM yyyy') : '—' },
    { key: 'uploadedAt', label: 'Uploaded', render: (r) => r.uploadedAt ? format(new Date(r.uploadedAt), 'dd MMM yyyy') : '—' },
    {
      key: 'actions', label: 'Actions', render: (r) => (
        <div className="flex gap-2">
          {r.fileUrl && <a href={r.fileUrl} target="_blank" rel="noreferrer" className="p-1.5 rounded hover:bg-slate-100 text-slate-500"><Download size={14} /></a>}
          <button onClick={() => { if (window.confirm('Delete?')) deleteMutation.mutate(r.id); }} className="p-1.5 rounded hover:bg-red-50 text-red-400"><Trash2 size={14} /></button>
        </div>
      )
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex justify-end">
        <Button onClick={() => setModalOpen(true)}><Plus size={16} /> Upload Document</Button>
      </div>
      <Table columns={columns} data={docs} loading={isLoading} />
      <Pagination page={page} totalPages={totalPages} onPageChange={setPage} />

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title="Upload Document">
        <div className="space-y-4">
          <div className="flex flex-col gap-1">
            <label className="text-sm font-medium text-slate-700">Document Type</label>
            <select
              className="border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white"
              value={form.documentType}
              onChange={(e) => setForm({ ...form, documentType: e.target.value })}
            >
              {['PASSPORT', 'VISA', 'CONTRACT', 'CERTIFICATE', 'OTHER'].map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>
          <div className="flex flex-col gap-1">
            <label className="text-sm font-medium text-slate-700">Expiry Date</label>
            <input type="date" className="border border-slate-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              value={form.expiryDate} onChange={(e) => setForm({ ...form, expiryDate: e.target.value })} />
          </div>
          <div className="flex flex-col gap-1">
            <label className="text-sm font-medium text-slate-700">File</label>
            <input type="file" className="text-sm" onChange={(e) => setFile(e.target.files[0])} />
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <Button variant="secondary" onClick={() => setModalOpen(false)}>Cancel</Button>
            <Button onClick={handleUpload} disabled={uploadMutation.isPending}>Upload</Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}
